import axios from "axios";

const apiClient = axios.create({
    baseURL: "http://localhost:3000/api",
    headers: { "Content-Type": "application/json" }
});

// Автоматически прикрепляем токен к каждому запросу
apiClient.interceptors.request.use(config => {
    const token = localStorage.getItem("accessToken");
    if (token) {
        config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
});

// Автоматически обновляем токен, если получили 401
apiClient.interceptors.response.use(
    (response) => response,
    async (error) => {
        const originalRequest = error.config;
        if (error.response && error.response.status === 401 && !originalRequest._retry) {
            originalRequest._retry = true;
            const rfToken = localStorage.getItem("refreshToken");
            if (rfToken) {
                try {
                    const res = await axios.post("http://localhost:3000/api/auth/refresh", { refreshToken: rfToken });
                    localStorage.setItem("accessToken", res.data.accessToken);
                    localStorage.setItem("refreshToken", res.data.refreshToken);
                    originalRequest.headers.Authorization = `Bearer ${res.data.accessToken}`;
                    return apiClient(originalRequest);
                } catch (e) {
                    localStorage.clear();
                    window.location.href = "/login";
                }
            }
        }
        return Promise.reject(error);
    }
);

export const api = {
    // Auth
    register: (data) => apiClient.post("/auth/register", data).then(res => res.data),
    login: (data) => apiClient.post("/auth/login", data).then(res => res.data),
    getMe: () => apiClient.get("/auth/me").then(res => res.data),

    // Products
    getProducts: () => apiClient.get("/products").then(res => res.data),
    createProduct: (p) => apiClient.post("/products", p).then(res => res.data),
    updateProduct: (id, p) => apiClient.put(`/products/${id}`, p).then(res => res.data),
    deleteProduct: (id) => apiClient.delete(`/products/${id}`)
};
